        ctx.fillStyle = '#f0c84a'; ctx.fillRect(X0 + 28 + mw - 1, Y0 - 12 * TS, 1, 12 * TS); ctx.fillRect(X0 + SW - 28 - mw, Y0 - 12 * TS, 1, 12 * TS);
        for (const px of [X0, X0 + SW - 28]) { ctx.fillStyle = '#e8b838'; ctx.fillRect(px, Y0 - 13 * TS, 28, 13 * TS); ctx.fillStyle = '#fff0a0'; ctx.fillRect(px + 2, Y0 - 13 * TS, 3, 13 * TS); ctx.fillStyle = '#8a6a1a'; ctx.fillRect(px + 22, Y0 - 13 * TS, 4, 13 * TS); for (let y = Y0 - 13 * TS + 6; y < Y0; y += 16) { ctx.fillStyle = '#8a6a1a'; ctx.fillRect(px + 7, y, 14, 2); } }
        ctx.fillStyle = '#9a1a28'; ctx.fillRect(X0, Y0 - 14 * TS, SW, 22); ctx.fillStyle = '#c4303c'; ctx.fillRect(X0, Y0 - 14 * TS, SW, 3); ctx.fillStyle = '#e8b838'; ctx.fillRect(X0, Y0 - 14 * TS + 19, SW, 3);
        for (let x = X0 + 6; x < X0 + SW - 6; x += 12) { ctx.fillStyle = '#e8b838'; ctx.fillRect(x, Y0 - 14 * TS + 22, 2, 5); }
        DD.text('WENDY KERBY PERFORMING ARTS CENTER', X0 + SW / 2, Y0 - 14 * TS + 8, '#fff0a0', 1, '#4a0a14', 'center');
