      DD.art.motes(G, '#ffd8a0', 22, 0.35);
      const vg = ctx.createRadialGradient(160, 100, 90, 160, 100, 230); vg.addColorStop(0, 'rgba(0,0,0,0)'); vg.addColorStop(1, 'rgba(20,6,10,0.32)'); ctx.fillStyle = vg; ctx.fillRect(0, 0, 320, 180);
