// ================================================================ world pass: the documentary crew (the world's new enemy) and the optional challenge room
// The crew is Josh Lorton's Mister America documentary crew (S11: Tim "send a shame on you out to Josh Lorton", Gregg's VFA footage cut from it): a boom-mic operator who tails
// you with the fuzzy mic held out toward you, winds the pole back (30 frames, with a red "!"), swings it, then sags and rests. Stomp it any time (2 popcorn). It hurts everywhere
// but when resting. The room hangs under the stage (rows below the main level) and is entered through a door in the Dot secret: press Down on the door; the room's X door brings you back.
(function () {
  const TS = 16, CFG = { mainH: 32, name: 'GLIDE PATH', bg: ['#1a1008', '#3a2412', 'rgba(255,230,160,0.07)'] };
  DD.defineEntity('w8crew', {
    spawn: t => ({ x: t.x + 1, y: t.y + 32 - 26, w: 14, h: 26, vx: 0, vy: 0, dir: -1, st: 'walk', t: 0, x0: t.x, cool: 0, ext: 0 }),
    update(e, G) {
      const p = G.pl; e.t++; if (e.cool > 0) e.cool--;
      e.vy = Math.min(e.vy + 0.4, 6); if (DD.moveY(e, e.vy, false)) e.vy = 0;
      const dx = DD.cx(p) - DD.cx(e), same = Math.abs((p.y + p.h) - (e.y + e.h)) < 26;
      const step = v => {   // move, turning back at a wall or a ledge
        const front = e.dir > 0 ? e.x + e.w + 1 : e.x - 3;
        if (!DD.T(Math.floor(front / TS), Math.floor((e.y + e.h + 1) / TS)) && DD.boxFree(front, e.y + e.h + 1, 2, 3)) return false;
        if (DD.moveX(e, v * e.dir, false)) return false;
        return true;
      };
      const reach = n => { if (n > 0 && e.ext === 0) { e.ext = 20; if (e.dir < 0) e.x -= 20; e.w += 20; } else if (n === 0 && e.ext) { if (e.dir < 0) e.x += 20; e.w -= 20; e.ext = 0; } };
      if (e.st === 'walk') {
        if (!step(0.45)) e.dir = -e.dir;
        if (Math.abs(e.x - e.x0) > 64) e.dir = e.x > e.x0 ? -1 : 1;
        if (e.cool === 0 && same && Math.abs(dx) < 110) { e.st = 'tail'; e.t = 0; }
      } else if (e.st === 'tail') {          // tails you, the boom held out toward you
        e.dir = dx < 0 ? -1 : 1; step(0.8);
        if (Math.abs(dx) < 40 && same) { e.st = 'wind'; e.t = 0; e.dir = dx < 0 ? -1 : 1; DD.SFX.buzz && DD.SFX.buzz(); }
        else if (e.t > 140 || !same || Math.abs(dx) > 150) { e.st = 'walk'; e.t = 0; e.cool = 60; }
      } else if (e.st === 'wind') {          // the pole goes back: 30 frames of warning
        if (e.t >= 30) { e.st = 'swing'; e.t = 0; reach(1); DD.SFX.thud && DD.SFX.thud(); }
      } else if (e.st === 'swing') {         // the swing: the mic reaches 20px further for 12 frames
        if (e.t >= 12) { reach(0); e.st = 'rest'; e.t = 0; }
      } else if (e.st === 'rest') {          // the pole droops, he catches his breath: free stomp, harmless
        if (e.t >= 60) { e.st = 'walk'; e.t = 0; e.cool = 90; }
      }
      if (e.y > DD.L.H * TS + 60) e.dead = true;
    },
    stomp(e) { if (e.ext) { if (e.dir < 0) e.x += 20; e.w -= 20; e.ext = 0; } e.dead = true; DD.addGot(2, DD.cx(e), e.y); DD.SFX.stomp && DD.SFX.stomp(); DD.burst && DD.burst(DD.cx(e), e.y + 10, 8); DD.stars && DD.stars(DD.cx(e), e.y, 4, '#ffe680'); return true; },
    touch(e) { if (e.st !== 'rest') DD.hurt(DD.cx(e)); },
    draw(e, ctx, G) {
      const f = e.dir, bw = 14, X = DD.wx(e.x + (e.ext && e.dir < 0 ? 20 : 0)), Y = DD.wy(e.y), cx = X + bw / 2, bob = e.st === 'walk' || e.st === 'tail' ? Math.abs(Math.sin(e.t / 5)) : 0;
      const hy = Y + 5 - bob, legA = (e.st === 'walk' || e.st === 'tail') ? Math.floor(e.t / 6) % 2 : 0;
      DD.spr('w8_crew_' + legA, cx, Y + 26 - Math.round(bob), f > 0);   // charpass: the sprite (the boom pole and effects stay live)
      // the boom pole and its fuzzy windscreen
      let ang = -0.55; if (e.st === 'tail') ang = -0.12; if (e.st === 'wind') ang = -0.55 - Math.min(1, e.t / 30) * 0.9; if (e.st === 'swing') ang = 0.0; if (e.st === 'rest') ang = 0.9;
      const len = e.st === 'swing' ? 30 : 22, px = cx + f * 3, py = Y + 12 - bob, ex = px + f * Math.cos(ang) * len, ey = py + Math.sin(ang) * len;
      ctx.strokeStyle = '#303540'; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(ex, ey); ctx.stroke();
      ctx.fillStyle = '#9a9aa6'; ctx.fillRect(Math.round(ex) - 3, Math.round(ey) - 2, 7, 5); ctx.fillStyle = '#c8c8d2'; ctx.fillRect(Math.round(ex) - 2, Math.round(ey) - 2, 4, 2); ctx.fillStyle = '#7a7a86'; ctx.fillRect(Math.round(ex) - 3, Math.round(ey) + 2, 7, 1);
      if (e.st === 'wind') DD.text('!', cx, Y - 8, (e.t >> 2) % 2 ? '#ffffff' : '#ff6a5a', 2, '#000', 'center');
      if (e.st === 'rest') for (let i = 0; i < 2; i++) { const a = G.frame / 8 + i * 3.1; DD.text('*', cx + Math.cos(a) * 8, hy - 8 + Math.sin(a) * 2, '#ffe680', 1, '#000', 'center'); }
    },
  });
  DD.defineEntity('w8door', {   // a service door: Down on it to go through (the way into a room, or the way back); the X door at the end of the room takes you out at once
    spawn: t => { const a = t.args || []; const tall = a[3] !== 0; return { x: t.x + 1, y: t.y + (tall ? 0 : 0), w: 14, h: tall ? 32 : 16, dtx: a[0], dty: a[1], mode: a[2] || 'in', cool: 20, lit: 0 }; },
    update(e, G) {
      if (e.cool > 0) e.cool--; e.lit++;
      const p = G.pl;
      e.hid = !!DD.T(Math.floor((e.x + 7) / TS), Math.floor(e.y / TS));   // a door in a sealed pocket stays hidden until its floor is broken
      if (e.hid || e.cool > 0) return;
      if (DD.door(e)) {   // Down on the door, in or out
        p.x = e.dtx * TS + 8 - p.w / 2; p.y = (e.dty + 1) * TS - p.h; p.vx = 0; p.vy = 0; p.slam = 0; G.safe = { x: p.x, y: p.y };
        G.s.room = e.mode === 'in'; G.s.snap = 3; G.shake = 0;
        DD.bodies.forEach(b => { if (b.kind === 'w8door') b.cool = 30; });
        DD.SFX.cp && DD.SFX.cp(); DD.stars && DD.stars(DD.cx(p), p.y + p.h / 2, 8, '#ffe680');
        if (e.mode === 'in') DD.float(DD.cx(p), p.y - 12, CFG.name, '#ffe680'); else if (e.mode === 'out') DD.float(DD.cx(p), p.y - 12, 'BACK ON AIR', '#ffe680');
      }
    },
    draw(e, ctx, G) {
      if (e.hid) return;
      const X = DD.wx(e.x), Y = DD.wy(e.y), pulse = (G.frame >> 4) % 2, near = Math.abs(DD.cx(G.pl) - DD.cx(e)) < 52 && Math.abs(G.pl.y - e.y) < 40;
      ctx.fillStyle = '#e8c860'; ctx.fillRect(X - 1, Y - 1, e.w + 2, e.h + 2);
      ctx.fillStyle = e.mode === 'out' ? '#5a1620' : '#14060a'; ctx.fillRect(X + 1, Y + 1, e.w - 2, e.h - 2);
      ctx.fillStyle = e.mode === 'out' ? '#ffe680' : '#d62a2a'; ctx.fillRect(X + 1, Y + 1, e.w - 2, 1);
      if (e.h > 20) { ctx.fillStyle = '#ffe680'; ctx.fillRect(X + e.w - 4, Y + e.h / 2, 1, 2); }
      if (e.mode !== 'out' && (near || e.mode === 'in')) {   // a down arrow over the door
        const by = Y - 8 + (pulse ? 1 : 0); ctx.fillStyle = near ? '#ffffff' : '#ffe680';
        ctx.fillRect(X + e.w / 2 - 1, by, 3, 3); ctx.fillRect(X + e.w / 2 - 3, by + 3, 7, 1); ctx.fillRect(X + e.w / 2 - 2, by + 4, 5, 1); ctx.fillRect(X + e.w / 2 - 1, by + 5, 3, 1);
      }
      if (e.mode === 'out') { ctx.save(); ctx.globalCompositeOperation = 'lighter'; const g = ctx.createRadialGradient(X + 7, Y + 14, 2, X + 7, Y + 14, 34); g.addColorStop(0, 'rgba(255,200,90,0.35)'); g.addColorStop(1, 'rgba(255,200,90,0)'); ctx.fillStyle = g; ctx.fillRect(X - 30, Y - 22, 74, 72); ctx.restore(); }
    },
    stomp: () => false, touch() {},
  });
  // wrap the level script: the room's camera, its own backdrop, and no stage logic running underneath it
  const S = window.LEVEL.script || (window.LEVEL.script = {}), O = Object.assign({}, S);
  S.init = G => { G.s.room = false; G.s.snap = 0; O.init && O.init(G); };
  S.update = G => {
    if (!G.s.room) O.update && O.update(G);
    // the room hangs below the level, so a pit is only the old level's depth deep: the iris closes as soon as you fall out of the stage, not after a fall through the void under it
    if (!G.s.room && !G.fall && G.pl.y > CFG.mainH * TS + 40) { DD.SFX.fall && DD.SFX.fall(); G.fall = { t: 0 }; }
  };
  S.camera = (G, c, snap) => {
    const p = G.pl, LH = DD.L.H * TS;
    if (G.s.snap > 0) { G.s.snap--; c.x = DD.clamp(DD.cx(p) - DD.VW / 2, 0, DD.L.W * TS - DD.VW); c.y = DD.clamp(DD.bot(p) - DD.VH * 0.62, 0, (G.s.room ? LH : CFG.mainH * TS) - DD.VH); }
    if (G.s.room) { c.y = DD.clamp(c.y, 0, LH - DD.VH); return; }
    O.camera && O.camera(G, c, snap);
    c.y = Math.min(c.y, CFG.mainH * TS - DD.VH);
  };
  S.drawBG = (ctx, G) => {
    if (!G.s.room) { O.drawBG && O.drawBG(ctx, G); return; }
    const VW = DD.VW, VH = DD.VH, c = G.cam, g = ctx.createLinearGradient(0, 0, 0, VH);
    g.addColorStop(0, CFG.bg[0]); g.addColorStop(1, CFG.bg[1]); ctx.fillStyle = g; ctx.fillRect(0, 0, VW, VH);
    ctx.fillStyle = CFG.bg[2]; for (let x = -((c.x * 0.4) % 32); x < VW; x += 32) ctx.fillRect(Math.round(x), 0, 1, VH); for (let y = -((c.y * 0.4) % 32); y < VH; y += 32) ctx.fillRect(0, Math.round(y), VW, 1);
  };
})();
